import { useText } from '@adobe-commerce/elsie/i18n';
import { classes } from '@adobe-commerce/elsie/lib';
import {
  FunctionComponent,
  HTMLAttributes,
  useCallback,
  useEffect,
  useRef,
} from 'preact/compat';
import { useId } from 'preact/hooks';
import { Button } from '../Button';
import { Close as CloseSVG } from '@adobe-commerce/elsie/icons';
import { VNode } from 'preact';
import { Portal } from '../Portal/Portal';

import '@adobe-commerce/elsie/components/Modal/Modal.css';

const FOCUSABLE_SELECTOR =
  'a[href], button, input, textarea, select, details, [tabindex]:not([tabindex="-1"])';

export interface ModalProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'size' | 'title'> {
  size?: 'small' | 'medium' | 'full';
  title?: VNode;
  centered?: boolean;
  onClose?: () => void;
  backgroundDim?: boolean;
  clickToDismiss?: boolean;
  escapeToDismiss?: boolean;
  showCloseButton?: boolean;
}

export const Modal: FunctionComponent<ModalProps> = ({
  size = 'small',
  title = null,
  centered = false,
  backgroundDim = true,
  clickToDismiss = true,
  escapeToDismiss = true,
  onClose,
  showCloseButton = true,
  className,
  children = null,
  ...props
}) => {
  const titleId = useId();
  const bodyRef = useRef<HTMLDivElement | null>(null);
  const previouslyFocusedElement = useRef<HTMLElement | null>(null);

  const handleOnClose = useCallback(() => {
    onClose?.();
  }, [onClose]);

  const translations = useText({
    modalCloseLabel: 'Dropin.Modal.Close.label',
  });

  // Close on background click
  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      const modal = document.querySelector('.dropin-modal');
      const modalBody = document.querySelector('.dropin-modal__body');

      if (
        clickToDismiss &&
        modal &&
        modalBody &&
        !modalBody.contains(event.target as Node)
      ) {
        handleOnClose();
      }
    };

    document.addEventListener('mousedown', handleOutsideClick);

    return () => {
      document.removeEventListener('mousedown', handleOutsideClick);
    };
  }, [handleOnClose, clickToDismiss]);

  // Close on ESC
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && escapeToDismiss) {
        handleOnClose();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleOnClose, escapeToDismiss]);

  // Prevent document scrolling
  useEffect(() => {
    const scrollingElement = document.scrollingElement as HTMLElement;

    const defaultOverflowValue = scrollingElement.style.overflow;

    scrollingElement.style.overflow = 'hidden';

    return () => {
      scrollingElement.style.overflow = defaultOverflowValue;
    };
  }, []);

  // Move focus into the modal on open, restore it to the trigger on close
  useEffect(() => {
    previouslyFocusedElement.current = document.activeElement as HTMLElement;

    const body = bodyRef.current as HTMLDivElement;
    const [firstFocusable] = body.querySelectorAll<HTMLElement>(
      FOCUSABLE_SELECTOR
    );

    (firstFocusable ?? body).focus();

    return () => {
      previouslyFocusedElement.current?.focus();
    };
  }, []);

  // Trap Tab focus inside the modal
  useEffect(() => {
    const body = bodyRef.current as HTMLDivElement;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;

      const focusable = body.querySelectorAll<HTMLElement>(
        FOCUSABLE_SELECTOR
      );

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (!first || !last) return;

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    body.addEventListener('keydown', handleKeyDown);

    return () => {
      body.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  return (
    <Portal>
      <div
        className={classes([
          'dropin-modal',
          ['dropin-modal--dim', backgroundDim],
        ])}
      >
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby={title ? titleId : undefined}
          tabIndex={-1}
          {...props}
          ref={bodyRef}
          className={classes([
            'dropin-modal__body',
            [`dropin-modal__body--${size}`, size],
            className,
          ])}
        >
          <div
            className={classes([
              'dropin-modal__header',
              ['dropin-modal__header-title', !!title],
            ])}
          >
            {title && (
              <div
                id={titleId}
                className={classes(['dropin-modal__header-title-content'])}
              >
                {title}
              </div>
            )}

            {showCloseButton && (
              <Button
                aria-label={translations.modalCloseLabel}
                variant="tertiary"
                className="dropin-modal__header-close-button"
                onClick={handleOnClose}
                icon={<CloseSVG />}
              />
            )}
          </div>

          <div
            className={classes([
              'dropin-modal__content',
              ['dropin-modal__body--centered', centered],
            ])}
          >
            {children}
          </div>
        </div>
      </div>
    </Portal>
  );
};
